<template>
  <div>
    <div class="container">
        <Mjuni/> 
    </div>
    <div class="d-flex mb-2">
      <h5 class="me-auto">{{ form }}</h5>
      <button @click="toggleNew" class="btn" :class="!newEntity ? 'btn-primary' : 'btn-danger'">
        {{ !newEntity ? '+ NEW' : 'X' }}
      </button>
    </div>

    <form v-if="newEntity" @submit.prevent="submit">
      <div class="row mb-3">
      <div v-for="field in fields" :key="field.id" :class="field.field_type === 'textarea' ? 'col-md-12' : 'col-md-4'">
        <label class="form-label small text-muted">{{ field.field_label }}</label>

        <input v-if="field.field_type === 'text' || field.field_type === 'email'"
               v-model="formData[field.field_name]"
               :type="field.field_type"
               class="form-control form-control-sm"
               :required="field.is_required"
               :placeholder="field.field_label" />

        <input v-else-if="field.field_type === 'number'"
               type="number"
               v-model="formData[field.field_name]"
               class="form-control form-control-sm"
               :placeholder="field.field_label" />

        <input v-else-if="field.field_type === 'date'"
               type="date"
               v-model="formData[field.field_name]"
               class="form-control form-control-sm" />

        <textarea v-else-if="field.field_type === 'textarea'"
                  v-model="formData[field.field_name]"
                  class="form-control form-control-sm"
                  rows="3"
                  :placeholder="field.field_label"></textarea>

        <select v-else-if="field.field_type === 'select'"
                v-model="formData[field.field_name]"
                class="form-select form-select-sm">
          <option value="">Select...</option>
          <option v-for="o in field.options" :key="o" :value="o">{{ o }}</option>
        </select>

        <select v-else-if="field.field_type === 'relation'"
                v-model="formData[field.field_name]"
                class="form-select form-select-sm"
                :required="field.is_required">
          <option value="">Select...</option>
          <option v-for="r in relatedData[field.field_name]" :key="r.id" :value="r.id">
            {{ r.name || r.title || r.label || `#${r.id}` }}
          </option>
        </select>
      </div>
      </div>


      <div class="d-flex gap-2">
        <button class="btn btn-sm btn-dark" :disabled="saving">
          <span v-if="saving" class="spinner-border spinner-border-sm me-1"></span>
          {{ saving ? 'Saving...' : editingId ? 'Update' : 'Save' }}
        </button>
        <button v-if="editingId" type="button" class="btn btn-sm btn-outline-secondary" @click="cancelEdit">
          Cancel
        </button>
      </div>
    </form>

    <hr />

    <table v-if="rows.length" class="table table-sm table-bordered table-hover">
      <thead class="table-light">
        <tr>
          <th v-for="f in fields" :key="f.id" class="small text-muted fw-semibold">
            {{ f.field_label }}
          </th>
          <th class="small text-muted fw-semibold" style="width: 90px;">Actions</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="row in rows" :key="row.id">
          <td v-for="f in fields" :key="f.id" class="small align-middle">
            {{ f.field_type === 'relation' ? getRelatedDisplay(row, f) : row[f.field_name] }}
          </td>
          <td class="small align-middle">
            <div class="d-flex gap-1">
              <button class="btn btn-xs btn-outline-primary" style="font-size:11px;padding:1px 7px;" @click="editRow(row)">
                Edit
              </button>
              <button
                class="btn btn-xs btn-outline-danger"
                style="font-size:11px;padding:1px 7px;"
                :disabled="deletingId === row.id"
                @click="deleteRow(row.id)"
              >
                {{ deletingId === row.id ? '...' : 'Del' }}
              </button>
            </div>
          </td>
        </tr>
      </tbody>
    </table>

    <div v-else-if="loading" class="text-center text-muted py-4">
      <span class="spinner-border spinner-border-sm me-1"></span> Loading...
    </div>

    <div v-else class="text-center text-muted py-4 border rounded" style="border-style:dashed!important;">
      No records found
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, inject } from 'vue'
import axios from 'axios'

const showMessage = inject('showMessage')
const showError   = inject('showError')

const props = defineProps({ form: { type: String, required: true } })

const fields      = ref([])
const formData    = ref({})
const relatedData = ref({})
const rows        = ref([])
const newEntity   = ref(false)
const loading     = ref(false)
const saving      = ref(false)
const editingId   = ref(null)
const deletingId  = ref(null)

const api = axios.create({ baseURL: 'https://bushman.ink/api/v2/' })

const loadFields = async () => {
  try {
    const res = await api.get('forms')
    const formObj = res.data.find(f => f.name === props.form)
    fields.value = formObj?.fields ?? []

    for (const f of fields.value) {
      if (f.field_type === 'relation' && f.related_form?.name) {
        const related = await api.get(`modules/${f.related_form.name}`)
        relatedData.value[f.field_name] = related.data
      }
      formData.value[f.field_name] = ''
    }
  } catch {
    showError?.('Failed to load form.')
  }
}

const loadRows = async () => {
  loading.value = true
  try {
    const res = await api.get(`modules/${props.form}`)
    rows.value = res.data
  } finally {
    loading.value = false
  }
}

const getRelatedDisplay = (row, field) => {
  const val = row[field.field_name]
  if (!val) return '—'
  if (typeof val === 'object') return val.name || val.title || val.label || `#${val.id}`
  return val
}

const clearForm = () => {
  for (const f of fields.value) formData.value[f.field_name] = ''
  editingId.value = null
}

const toggleNew = () => {
  newEntity.value = !newEntity.value
  if (!newEntity.value) cancelEdit()
}

const cancelEdit = () => {
  clearForm()
  newEntity.value = false
}

// Populate form with row data for editing
const editRow = (row) => {
  editingId.value = row.id
  for (const f of fields.value) {
    const val = row[f.field_name]
    // For relation fields, extract the id if it's an object
    formData.value[f.field_name] = (f.field_type === 'relation' && typeof val === 'object')
      ? val?.id ?? ''
      : val ?? ''
  }
  newEntity.value = true
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

const submit = async () => {
  saving.value = true
  try {
    if (editingId.value) {
      await api.put(`modules/${props.form}/${editingId.value}`, formData.value)
      showMessage?.('Updated successfully.')
    } else {
      await api.post(`modules/${props.form}`, formData.value)
      showMessage?.('Saved successfully.')
    }
    cancelEdit()
    await loadRows()
  } catch {
    showError?.('Failed to save.')
  } finally {
    saving.value = false
  }
}

const deleteRow = async (id) => {
  if (!confirm('Delete this record? This cannot be undone.')) return

  deletingId.value = id
  try {
    await api.delete(`modules/${props.form}/${id}`)
    showMessage?.('Record deleted.')
    await loadRows()
  } catch (err) {
    showError?.(err.response?.data?.message ?? 'Failed to delete record.')
  } finally {
    deletingId.value = null
  }
}

onMounted(async () => {
  await loadFields()
  await loadRows()
})
</script>